"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[762],{5762:(n,t,i)=>{i.r(t),i.d(t,{default:()=>h});let h={id:"zh",viName:"tiếng Trung",flag:"\uD83C\uDDE8\uD83C\uDDF3",scriptMode:"cjk",minDialogueChars:0,minBoldWords:1,storagePrefix:"lingua-zh-",defaults:{level:"A1",profile:"everyday"},mascot:{kind:"panda",badge:"\uD83D\uDC3C Linh vật"},nameEn:"Chinese (Mandarin)",nameNative:"中文",appTitle:"Teacher AI — Học tiếng Trung c\xf9ng AI",appDescription:"Luyện giao tiếp tiếng Trung (Quan Thoại) c\xf9ng gia sư AI, d\xe0nh cho người Việt.",shortName:"Teacher AI",speechLang:"zh-CN",langPrefix:"zh",levelSystem:"HSK",levelLabels:{A1:"HSK 1-2",A2:"HSK 3",B1:"HSK 4",B2:"HSK 5"},phoneticName:"pinyin",targetScript:/[㐀-鿿]/,targetRun:/[㐀-鿿][㐀-鿿　-〿＀-￯\s、。！？!?,.]*/g,sentenceEnd:"。！？",recognitionHint:"N\xf3i bằng tiếng Trung",welcome:{headline:"Xin ch\xe0o! C\xf9ng n\xf3i tiếng Trung tự tin hơn nh\xe9.",greeting:"你好!"},pronunciationFocus:"four tones and the neutral tone, tone sandhi (不 / 一 and two third tones in a row), aspirated vs unaspirated (b/p, d/t, g/k, j/q, zh/ch, z/c), retroflex zh/ch/sh/r vs z/c/s, j/q/x, \xfc vs u, -n vs -ng finals, er-hua",promptNotes:'Teaching language: Mandarin Chinese (中文, Simplified characters 简体字). Level system: HSK (HSK 1-2 = A1, HSK 3 = A2, HSK 4 = B1, HSK 5 = B2).\n- Write every Chinese sentence the learner should say inside double quotes "…", and IMMEDIATELY after it give its pinyin WITH TONE MARKS in square brackets, e.g. "你好" [nǐ hǎo]. At HSK 1-3 always add pinyin; at HSK 4-5 only for new or difficult words. Never write pinyin anywhere else. Text in square brackets is never read aloud.\n- Use Simplified characters only, and vocabulary of the matching HSK level (HSK 1-2: about 300 common words such as 我, 你, 吃, 喝, 学校).\n- Always point out the tone of a new word and warn about tone changes (不 + 4th tone → b\xfa, 一 before 4th tone → y\xed, 3rd + 3rd → 2nd + 3rd).\n- Typical mistakes of Vietnamese learners to watch for: tones (especially 2nd vs 3rd), zh/ch/sh vs z/c/s, the aspirated/unaspirated pairs (b/p, d/t, g/k), j/q/x, \xfc; word order (time and place before the verb), measure words (个, 本, 杯), 了 / 过 / 着, 的 / 得 / 地, and Sino-Vietnamese false friends.',pedagogy:{A1:"- Explain mostly in Vietnamese (about 80%). Chinese only in very short model sentences (2–6 characters), each followed by its pinyin with tone marks in [brackets] and the Vietnamese meaning.\n- One new item per turn. Tasks: repeat after me, choose A or B, complete one word. Accept one-word answers, then model the full sentence.\n- Drill tones explicitly (mā m\xe1 mǎ m\xe0). Correct only the most important mistake each turn; be very encouraging.",A2:'- Mix Vietnamese explanations (about 50%) with simple Chinese (HSK 3 grammar: 了, 过, 在, 正在, 把, 比, 可以/能/会, 一边……一边……). Add pinyin in [brackets] to every Chinese sentence.\n- Give a hint like (Gợi \xfd: "比") for each task. Tasks: full-sentence answers, simple role-plays with 2–3 exchanges.\n- Correct up to two mistakes per turn, mainly tones, word order and measure words.',B1:'- Teach mostly in Chinese (about 70%); give pinyin in [brackets] only for new or difficult words. Use Vietnamese only for tricky grammar or meaning.\n- Role-plays with longer exchanges; ask follow-up "why / how" questions. Introduce 把 / 被 sentences, complements of result and direction, 虽然……但是……, 如果……就……, 越来越.\n- Correct every error that affects meaning, plus unnatural word choice; offer a more natural phrase.',B2:"- Teach in Chinese; use Vietnamese only if the learner asks. Cover 成语 and set phrases, formal and written style, 连……都……, 既然……就……, 不但……而且……, business register.\n- Discussions, negotiations and problem-solving situations; challenge the learner's opinions. Give pinyin in [brackets] only for rare words.\n- Correct accuracy, register and naturalness, including better word choices."},accents:[{id:"beijing",group:"Trung Quốc",flag:"\uD83C\uDDE8\uD83C\uDDF3",name:"Phổ th\xf4ng – Bắc Kinh",locales:["zh-cn","zh"],prompt:"a standard Mainland Mandarin (Putonghua) accent",sample:"你好。今天我们一起练习中文吧。"},{id:"taiwan",group:"Đ\xe0i Loan",flag:"\uD83C\uDDF9\uD83C\uDDFC",name:"Quốc ngữ – Đ\xe0i Loan",locales:["zh-tw"],prompt:"a Taiwan Mandarin accent with a soft, gentle rhythm",sample:"你好。今天我們一起練習中文吧。"}],profiles:[{id:"everyday",title:"Tiếng Trung giao tiếp hằng ng\xe0y",subtitle:"Ch\xe0o hỏi, mua sắm, ăn uống, nhờ vả",icon:"everyday",color:"yellow",scene:"L\xe0m quen với người mới",prompt:"Xin ch\xe0o! H\xf4m nay ch\xfang ta luyện giao tiếp tiếng Trung hằng ng\xe0y. C\xf4 sẽ dạy em từng bước nh\xe9.",words:["你好。","请多关照。","谢谢你。"]},{id:"travel",title:"Tiếng Trung du lịch",subtitle:"Kh\xe1ch sạn, nh\xe0 h\xe0ng, t\xe0u điện, hỏi đường",icon:"travel",color:"orange",scene:"L\xe0m thủ tục nhận ph\xf2ng kh\xe1ch sạn",prompt:"Xin ch\xe0o! H\xf4m nay ch\xfang ta luyện tiếng Trung khi đi du lịch Trung Quốc. C\xf4 sẽ dạy em từng bước nh\xe9.",words:["我订了房间。","洗手间在哪儿?","多少钱?"]},{id:"business",title:"Tiếng Trung c\xf4ng sở",subtitle:"Họp h\xe0nh, email, điện thoại, b\xe1o c\xe1o",icon:"business",color:"blue",scene:"Trao đổi với đồng nghiệp trong c\xf4ng ty",prompt:"Xin ch\xe0o! H\xf4m nay ch\xfang ta luyện tiếng Trung c\xf4ng sở. C\xf4 sẽ dạy em từng bước nh\xe9.",words:["我先走了。","好的,明白了。","我来确认一下。"]},{id:"technology",title:"Tiếng Trung ng\xe0nh c\xf4ng nghệ",subtitle:"Kỹ sư IT, họp, b\xe1o lỗi, phỏng vấn",icon:"technology",color:"purple",scene:"Họp buổi s\xe1ng với nh\xf3m ph\xe1t triển",prompt:"Xin ch\xe0o! H\xf4m nay ch\xfang ta luyện tiếng Trung ng\xe0nh c\xf4ng nghệ. Thầy/c\xf4 sẽ dạy em từng bước nh\xe9.",words:["这个问题已经解决了。","测试已经完成了。","我再确认一下需求。"]},{id:"healthcare",title:"Tiếng Trung chuy\xean ng\xe0nh y khoa",subtitle:"Điều dưỡng, b\xe1c sĩ, giao tiếp với bệnh nh\xe2n",icon:"healthcare",color:"green",scene:"Hỏi thăm triệu chứng bệnh nh\xe2n",prompt:"Xin ch\xe0o! H\xf4m nay ch\xfang ta luyện tiếng Trung chuy\xean ng\xe0nh y khoa. Thầy/c\xf4 sẽ dạy em từng bước nh\xe9.",words:["您哪儿不舒服?","您吃药了吗?","请稍等一下。"]},{id:"finance",title:"Tiếng Trung ng\xe0nh t\xe0i ch\xednh",subtitle:"Ng\xe2n h\xe0ng, kế to\xe1n, b\xe1o c\xe1o, đầu tư",icon:"finance",color:"pink",scene:"Tr\xecnh b\xe0y b\xe1o c\xe1o t\xe0i ch\xednh th\xe1ng",prompt:"Xin ch\xe0o! H\xf4m nay ch\xfang ta luyện tiếng Trung ng\xe0nh t\xe0i ch\xednh. Thầy/c\xf4 sẽ dạy em từng bước nh\xe9.",words:["销售额增长了。","比去年增长了百分之五。","请您确认一下。"]},{id:"refrigeration",title:"Tiếng Trung kỹ thuật điện lạnh c\xf4ng nghiệp",subtitle:"Kho lạnh, m\xe1y n\xe9n, NH3/CO2, an to\xe0n, bảo tr\xec",icon:"refrigeration",color:"blue",scene:"Nhận y\xeau cầu sửa kho lạnh",prompt:"Xin ch\xe0o! H\xf4m nay ch\xfang ta luyện tiếng Trung kỹ thuật điện lạnh c\xf4ng nghiệp. Thầy/c\xf4 sẽ dạy em từng bước nh\xe9.",words:["冷库不制冷了。","请先切断电源。","我检查一下压力。"]}],phraseMeanings:{"你好。":"Xin ch\xe0o.","请多关照。":"Mong được gi\xfap đỡ / xin chiếu cố.","谢谢你。":"Cảm ơn bạn.","我订了房间。":"T\xf4i đ\xe3 đặt ph\xf2ng trước.","洗手间在哪儿?":"Nh\xe0 vệ sinh ở đ\xe2u ạ?","多少钱?":"Bao nhi\xeau tiền ạ?","我先走了。":"T\xf4i xin ph\xe9p về trước ạ.","好的,明白了。":"V\xe2ng, t\xf4i hiểu rồi ạ.","我来确认一下。":"Để t\xf4i x\xe1c nhận lại một ch\xfat ạ.","这个问题已经解决了。":"Vấn đề n\xe0y đ\xe3 được giải quyết.","测试已经完成了。":"Kiểm thử đ\xe3 ho\xe0n tất.","我再确认一下需求。":"Để t\xf4i x\xe1c nhận lại y\xeau cầu.","您哪儿不舒服?":"B\xe1c thấy kh\xf3 chịu ở đ\xe2u?","您吃药了吗?":"B\xe1c đ\xe3 uống thuốc chưa?","请稍等一下。":"Xin chờ một ch\xfat.","销售额增长了。":"Doanh thu đ\xe3 tăng.","比去年增长了百分之五。":"Tăng 5% so với năm ngo\xe1i.","请您确认一下。":"Xin qu\xfd vị x\xe1c nhận gi\xfap.","冷库不制冷了。":"Kho lạnh kh\xf4ng l\xe0m lạnh nữa.","请先切断电源。":"Xin ngắt nguồn điện trước.","我检查一下压力。":"T\xf4i kiểm tra \xe1p suất một ch\xfat."},suggestions:{everyday:["你好,我是越南人。","请再说一遍,慢一点。","C\xf4 giải th\xedch lại bằng tiếng Việt gi\xfap em với.","这个多少钱?"],travel:["我要办理入住。","地铁站在哪儿?","C\xf4 hướng dẫn em c\xe1ch ph\xe1t \xe2m c\xe2u vừa rồi nh\xe9.","有英文菜单吗?"],business:["我先走了。","会议几点开始?","Thầy chỉ ra lỗi ngữ ph\xe1p gi\xfap em nh\xe9.","请把资料发给我。"],technology:["昨天我做完了登录页面。","我来说明一下重现步骤。","C\xf4 giải th\xedch lại bằng tiếng Việt gi\xfap em với.","请帮我审查一下代码。"],healthcare:["您从什么时候开始发烧?","请深呼吸。","C\xf4 hướng dẫn em c\xe1ch ph\xe1t \xe2m c\xe2u vừa rồi nh\xe9.","请不要担心。"],finance:["我想开一个账户。","利率是多少?","Thầy chỉ ra lỗi ngữ ph\xe1p gi\xfap em nh\xe9.","销售额比去年增长了。"],refrigeration:["冷库里现在几度?","可能是膨胀阀堵了。","Thầy giải th\xedch thuật ngữ n\xe0y bằng tiếng Việt nh\xe9.","氨泄漏时要马上撤离。"]},placement:[{level:"A1",question:"Điền v\xe0o chỗ trống: 我___学生。(T\xf4i l\xe0 sinh vi\xean.)",options:["是","很","在","有"],answer:0,explanation:"是 = l\xe0."},{level:"A1",question:"Điền v\xe0o chỗ trống: 你叫什么___?(Bạn t\xean l\xe0 g\xec?)",options:["时候","名字","地方","东西"],answer:1,explanation:"名字 = t\xean."},{level:"A1",question:"C\xe2u n\xe0o nghĩa l\xe0 “Bạn khỏe kh\xf4ng?”",options:["你好吗?","你是谁?","你去哪儿?","你几岁?"],answer:0,explanation:"你好吗 = bạn khỏe kh\xf4ng."},{level:"A1",question:"Điền v\xe0o chỗ trống: 我___北京工作。(T\xf4i l\xe0m việc ở Bắc Kinh.)",options:["有","去","在","是"],answer:2,explanation:"在 + nơi chốn + động từ."},{level:"A1",question:"Điền v\xe0o chỗ trống: 这个苹果___钱?(Quả t\xe1o n\xe0y bao nhi\xeau tiền?)",options:["哪","什么","多少","几"],answer:2,explanation:"多少钱 = bao nhi\xeau tiền."},{level:"A2",question:"Điền v\xe0o chỗ trống: 我昨天去商店___一件衣服。",options:["买过","买着","在买","买了"],answer:3,explanation:"了 sau động từ chỉ h\xe0nh động đ\xe3 ho\xe0n th\xe0nh."},{level:"A2",question:"Điền v\xe0o chỗ trống: 他___我高。(Anh ấy cao hơn t\xf4i.)",options:["比","跟","对","和"],answer:0,explanation:"A 比 B + t\xednh từ: so s\xe1nh hơn."},{level:"A2",question:"Điền v\xe0o chỗ trống: 我会说汉语，___说得不太好。",options:["所以","因为","但是","如果"],answer:2,explanation:"但是 = nhưng."},{level:"A2",question:"Điền v\xe0o chỗ trống: 你去过中国___?",options:["吗","啊","呢","吧"],answer:0,explanation:"C\xe2u hỏi c\xf3/kh\xf4ng d\xf9ng 吗."},{level:"A2",question:"Điền v\xe0o chỗ trống: 我们一起去吃饭___!(M\xecnh c\xf9ng đi ăn nh\xe9!)",options:["吗","吧","了","呢"],answer:1,explanation:"吧 d\xf9ng để rủ r\xea, đề nghị."},{level:"B1",question:"Điền v\xe0o chỗ trống: 门开___，请进。(Cửa đang mở, mời v\xe0o.)",options:["了","的","着","过"],answer:2,explanation:"V + 着 chỉ trạng th\xe1i k\xe9o d\xe0i."},{level:"B1",question:"Điền v\xe0o chỗ trống: 我把作业___了。",options:["做完","在做","做着","做"],answer:0,explanation:"C\xe2u chữ 把 cần bổ ngữ kết quả: 把作业做完了."},{level:"B1",question:"Chọn cặp từ nối đ\xfang: ___下雨，比赛___取消了。",options:["不但…而且","因为…所以","虽然…但是","如果…就"],answer:1,explanation:"因为…所以 = v\xec… n\xean…."},{level:"B1",question:"Điền v\xe0o chỗ trống: 他汉语说___很流利。",options:["得","的","地","了"],answer:0,explanation:"Bổ ngữ trạng th\xe1i: V + 得 + 很 + t\xednh từ."},{level:"B1",question:"Nghĩa của 「经验」?",options:["kế hoạch","kiểm tra","kinh nghiệm","kinh tế"],answer:2,explanation:"经验 (jīngy\xe0n) = kinh nghiệm."},{level:"B2",question:"Chọn cặp từ nối đ\xfang: ___你同意，我们___开始。",options:["只要…就","虽然…但是","不管…都","因为…所以"],answer:0,explanation:"只要…就 = chỉ cần… th\xec…."},{level:"B2",question:"Chọn c\xe2u đ\xfang.",options:["他的成绩提高很大的有。","他的成绩有了很大的提高。","他的成绩很大的有提高。","他的成绩有大的很提高。"],answer:1,explanation:"有了很大的提高 = đ\xe3 c\xf3 tiến bộ lớn."},{level:"B2",question:"Nghĩa của 「推迟」?",options:["ho\xe3n lại","c\xf4ng bố","th\xfac đẩy","hủy bỏ"],answer:0,explanation:"推迟 (tuīch\xed) = ho\xe3n lại."},{level:"B2",question:"Điền v\xe0o chỗ trống: 这件事___他来说并不难。",options:["给","对","跟","向"],answer:1,explanation:"对…来说 = đối với… m\xe0 n\xf3i."},{level:"B2",question:"Điền v\xe0o chỗ trống: 他一进门，___发现钱包不见了。",options:["才","就","也","还"],answer:1,explanation:"一…就… = vừa… liền…."}],tutors:{maya:{name:"Lin Laoshi",title:"C\xf4 gi\xe1o Trung Quốc",tagline:"Dịu d\xe0ng, ph\xe1t \xe2m chuẩn, ki\xean nhẫn hướng dẫn",description:"C\xf4 gi\xe1o nhiệt t\xecnh, sửa tỉ mỉ từng thanh điệu, ph\xe1t \xe2m v\xe0 ngữ ph\xe1p theo tr\xecnh độ của bạn.",greeting:"H\xf4m nay c\xf4 sẽ đồng h\xe0nh c\xf9ng em luyện n\xf3i tiếng Trung thật tự tin nh\xe9."},david:{name:"Wei Laoshi",title:"Thầy gi\xe1o Trung Quốc",tagline:"Điềm đạm, r\xf5 r\xe0ng, giỏi t\xecnh huống c\xf4ng sở",description:"Thầy gi\xe1o phong c\xe1ch chuy\xean nghiệp, phản xạ nhanh v\xe0 chuy\xean s\xe2u giao tiếp c\xf4ng việc.",greeting:"H\xf4m nay thầy sẽ c\xf9ng em luyện n\xf3i tiếng Trung thật tự nhi\xean nh\xe9."},alex:{name:"Panda",title:"Linh vật học tập",tagline:"Đ\xe1ng y\xeau, hồn nhi\xean, học tập kh\xf4ng \xe1p lực",description:"Ch\xfa gấu tr\xfac tr\xf2n xinh qu\xe0ng khăn đỏ, vui t\xednh, học tập kh\xf4ng \xe1p lực.",greeting:"C\xf9ng nhau học tiếng Trung thật vui n\xe0o!"}},grammarTopics:[{id:"shi-sentence",level:"A1",title:"C\xe2u giới thiệu: A 是 B",structure:"A 是 B / A 不是 B / A 是 B 吗?",overview:"是 (sh\xec) nối hai danh từ, gần như “l\xe0”. Phủ định đặt 不 trước 是 (đọc th\xe0nh b\xfa sh\xec). Muốn hỏi chỉ cần th\xeam 吗 ở cuối c\xe2u, kh\xf4ng đảo trật tự từ. Kh\xf4ng d\xf9ng 是 trước t\xednh từ: n\xf3i 我很忙, kh\xf4ng n\xf3i 我是忙.",examples:["我是学生。[wǒ sh\xec xu\xe9sheng] (T\xf4i l\xe0 học sinh.)","他不是老师。[tā b\xfa sh\xec lǎoshī] (Anh ấy kh\xf4ng phải gi\xe1o vi\xean.)","你是越南人吗?[nǐ sh\xec Yu\xe8n\xe1n r\xe9n ma] (Bạn l\xe0 người Việt Nam phải kh\xf4ng?)"],questions:[{prompt:"Chọn c\xe2u đ\xfang: “T\xf4i l\xe0 kỹ sư.”",options:["我是工程师。","我工程师是。","我是很工程师。"],answer:0,explanation:"Cấu tr\xfac A 是 B: 我是工程师."},{prompt:"Phủ định của 「我是医生。」 l\xe0:",options:["我不是医生。","我没是医生。","我是不医生。"],answer:0,explanation:"Đặt 不 trước 是: 不是 (đọc b\xfa sh\xec)."},{prompt:"C\xe1ch hỏi “Bạn l\xe0 người Trung Quốc phải kh\xf4ng?” đ\xfang l\xe0:",options:["你是中国人吗?","你吗是中国人?","吗你是中国人?"],answer:0,explanation:"Th\xeam 吗 v\xe0o cuối c\xe2u để hỏi c\xf3/kh\xf4ng."}]},{id:"tones",level:"A1",title:"Bốn thanh điệu v\xe0 biến điệu",structure:"mā (1) – m\xe1 (2) – mǎ (3) – m\xe0 (4) – ma (nhẹ)",overview:"Tiếng Trung c\xf3 4 thanh điệu v\xe0 thanh nhẹ: thanh 1 cao đều, thanh 2 đi l\xean, thanh 3 xuống rồi l\xean, thanh 4 đi xuống dứt kho\xe1t. Đổi thanh l\xe0 đổi nghĩa. Quy tắc biến điệu: hai thanh 3 đứng liền th\xec thanh đầu đọc th\xe0nh thanh 2 (你好 đọc n\xed hǎo); 不 đứng trước thanh 4 đọc b\xfa (不是 b\xfa sh\xec); 一 đứng trước thanh 4 đọc y\xed (一个 y\xed g\xe8), trước thanh 1, 2, 3 đọc y\xec (一天 y\xec tiān).",examples:["妈妈骂马。[māma m\xe0 mǎ] (Mẹ mắng con ngựa.)","你好![nǐ hǎo] (Xin ch\xe0o! — thực tế đọc n\xed hǎo)","我不是老师。[wǒ b\xfa sh\xec lǎoshī] (T\xf4i kh\xf4ng phải gi\xe1o vi\xean.)","我有一个朋友。[wǒ yǒu y\xed g\xe8 p\xe9ngyou] (T\xf4i c\xf3 một người bạn.)"],questions:[{prompt:"「妈」 mang thanh điệu n\xe0o?",options:["Thanh 1 (mā)","Thanh 2 (m\xe1)","Thanh 4 (m\xe0)"],answer:0,explanation:"妈 đọc mā, thanh 1: cao v\xe0 đều."},{prompt:"「你好」 khi n\xf3i nhanh thực tế đọc l\xe0:",options:["n\xed hǎo","nǐ h\xe0o","nī hǎo"],answer:0,explanation:"Hai thanh 3 liền nhau: thanh thứ nhất đọc th\xe0nh thanh 2."},{prompt:"「不是」 đọc l\xe0:",options:["b\xfa sh\xec","b\xf9 sh\xec","bǔ sh\xec"],answer:0,explanation:"不 đứng trước thanh 4 th\xec biến th\xe0nh thanh 2: b\xfa."}]},{id:"word-order",level:"A1",title:"Trật tự c\xe2u: thời gian v\xe0 nơi chốn đứng trước động từ",structure:"S + thời gian + nơi chốn + V + O",overview:"Trong tiếng Trung, từ chỉ thời gian đứng sau chủ ngữ (hoặc đầu c\xe2u), tiếp theo l\xe0 nơi chốn (在 + nơi chốn), rồi mới đến động từ. Người Việt hay đặt nơi chốn v\xe0 thời gian ở cuối c\xe2u n\xean dễ sai. Nhớ: “l\xe0m g\xec” lu\xf4n ở cuối; “khi n\xe0o, ở đ\xe2u” đứng trước n\xf3.",examples:["我明天在家学习。[wǒ m\xedngtiān z\xe0i jiā xu\xe9x\xed] (Ng\xe0y mai t\xf4i học ở nh\xe0.)","她每天早上七点起床。[tā měi tiān zǎoshang qī diǎn qǐchu\xe1ng] (Mỗi s\xe1ng 7 giờ c\xf4 ấy dậy.)","我们在饭店吃晚饭。[wǒmen z\xe0i f\xe0ndi\xe0n chī wǎnf\xe0n] (Ch\xfang t\xf4i ăn tối ở nh\xe0 h\xe0ng.)"],questions:[{prompt:"Chọn c\xe2u đ\xfang: “T\xf4i học tiếng Trung ở trường.”",options:["我在学校学中文。","我学中文在学校。","我学校在学中文。"],answer:0,explanation:"Nơi chốn (在学校) đứng trước động từ."},{prompt:"Chọn c\xe2u đ\xfang: “Ng\xe0y mai t\xf4i đi l\xe0m.”",options:["我明天上班。","我上班明天。","明天我上班了明天。"],answer:0,explanation:"Thời gian đứng trước động từ: 我明天上班."},{prompt:"Điền v\xe0o chỗ trống: 「我___图书馆看书。」",options:["在","有","是"],answer:0,explanation:"在 + nơi chốn + động từ: l\xe0m g\xec ở đ\xe2u."}]},{id:"adjectives",level:"A1",title:"T\xednh từ l\xe0m vị ngữ: 很 + t\xednh từ",structure:"S + 很 + Adj / S + 不 + Adj / S + Adj + 吗?",overview:"T\xednh từ l\xe0m vị ngữ kh\xf4ng cần động từ 是, thường c\xf3 很 đứng trước (很 ở đ\xe2y chỉ nhẹ, kh\xf4ng nhất thiết l\xe0 “rất”). Phủ định d\xf9ng 不 thay cho 很: 不好. Khi so s\xe1nh hai vật th\xec kh\xf4ng d\xf9ng 很 m\xe0 d\xf9ng 比 hoặc 更.",examples:["今天很热。[jīntiān hěn r\xe8] (H\xf4m nay n\xf3ng.)","这个菜不辣。[zh\xe8ge c\xe0i b\xfa l\xe0] (M\xf3n n\xe0y kh\xf4ng cay.)","你忙吗?[nǐ m\xe1ng ma] (Bạn c\xf3 bận kh\xf4ng?)"],questions:[{prompt:"Chọn c\xe2u đ\xfang: “C\xf4 ấy rất đẹp.”",options:["她很漂亮。","她是漂亮。","她漂亮很。"],answer:0,explanation:"T\xednh từ l\xe0m vị ngữ: S + 很 + Adj, kh\xf4ng d\xf9ng 是."},{prompt:"Phủ định của 「这个很贵。」 l\xe0:",options:["这个不贵。","这个没贵。","这个很不是贵。"],answer:0,explanation:"Phủ định t\xednh từ d\xf9ng 不."},{prompt:"Điền v\xe0o chỗ trống: 「天气___好。」(Thời tiết tốt.)",options:["很","是","有"],answer:0,explanation:"D\xf9ng 很 trước t\xednh từ l\xe0m vị ngữ."}]},{id:"measure-words",level:"A1",title:"Lượng từ: số + lượng từ + danh từ",structure:"Số + 量词 + Danh từ (个, 本, 杯, 张, 只, 件)",overview:"Khi đếm hoặc chỉ định danh từ, tiếng Trung bắt buộc c\xf3 lượng từ giữa số từ v\xe0 danh từ, giống “một cuốn s\xe1ch”, “một cốc nước” của tiếng Việt. 个 l\xe0 lượng từ d\xf9ng được rộng nhất. 两 d\xf9ng thay 二 trước lượng từ: 两个, kh\xf4ng n\xf3i 二个. Với 这/那 cũng c\xf3 lượng từ: 这个, 那本.",examples:["我要一杯咖啡。[wǒ y\xe0o y\xec bēi kāfēi] (T\xf4i muốn một cốc c\xe0 ph\xea.)","我有两本书。[wǒ yǒu liǎng běn shū] (T\xf4i c\xf3 hai quyển s\xe1ch.)","这件衣服多少钱?[zh\xe8 ji\xe0n yīfu duōshao qi\xe1n] (Chiếc \xe1o n\xe0y bao nhi\xeau tiền?)"],questions:[{prompt:"Điền lượng từ: 「我有三___书。」",options:["本","杯","只"],answer:0,explanation:"本 l\xe0 lượng từ của s\xe1ch, vở."},{prompt:"“Hai người bạn” n\xf3i l\xe0:",options:["两个朋友","二个朋友","两朋友"],answer:0,explanation:"Trước lượng từ d\xf9ng 两, v\xe0 phải c\xf3 lượng từ 个."},{prompt:"Điền lượng từ: 「我想喝一___茶。」",options:["杯","件","张"],answer:0,explanation:"杯 l\xe0 lượng từ của đồ uống đựng trong cốc."}]},{id:"le",level:"A2",title:"Trợ từ 了: h\xe0nh động đ\xe3 ho\xe0n th\xe0nh, sự thay đổi",structure:"V + 了 / 没(有) + V / ……了 (cuối c\xe2u)",overview:"了 sau động từ b\xe1o hiệu h\xe0nh động đ\xe3 ho\xe0n th\xe0nh. Phủ định qu\xe1 khứ d\xf9ng 没(有) v\xe0 bỏ 了: 我没吃饭. 了 ở cuối c\xe2u c\xf2n diễn tả t\xecnh huống mới hoặc sự thay đổi (下雨了: trời mưa rồi). Đừng d\xf9ng 了 cho th\xf3i quen lặp lại hay trạng th\xe1i: 我常常去 (kh\xf4ng 了).",examples:["我昨天看了一个电影。[wǒ zu\xf3tiān k\xe0n le y\xed g\xe8 di\xe0nyǐng] (H\xf4m qua t\xf4i đ\xe3 xem một bộ phim.)","我没吃早饭。[wǒ m\xe9i chī zǎof\xe0n] (T\xf4i chưa ăn s\xe1ng.)","下雨了。[xi\xe0 yǔ le] (Trời mưa rồi.)"],questions:[{prompt:"Phủ định của 「我吃了早饭。」 l\xe0:",options:["我没吃早饭。","我不吃了早饭。","我没吃了早饭。"],answer:0,explanation:"Phủ định qu\xe1 khứ d\xf9ng 没 v\xe0 bỏ 了."},{prompt:"Điền v\xe0o chỗ trống: 「他已经走___。」(Anh ấy đ\xe3 đi rồi.)",options:["了","着","过"],answer:0,explanation:"了 diễn tả h\xe0nh động đ\xe3 ho\xe0n th\xe0nh."},{prompt:"C\xe2u n\xe0o KH\xd4NG cần 了?",options:["我每天喝咖啡。","我昨天喝咖啡了。","天黑了。"],answer:0,explanation:"Th\xf3i quen lặp lại hằng ng\xe0y kh\xf4ng d\xf9ng 了."}]},{id:"guo-zai",level:"A2",title:"过, 在 v\xe0 正在: đ\xe3 từng v\xe0 đang l\xe0m",structure:"V + 过 / 在 + V / 正在 + V (+ 呢)",overview:"V + 过 diễn tả kinh nghiệm đ\xe3 từng l\xe0m trong qu\xe1 khứ (kh\xf4ng c\xf2n tiếp diễn); phủ định l\xe0 没 + V + 过. 在 hoặc 正在 đặt trước động từ diễn tả h\xe0nh động đang diễn ra, cuối c\xe2u c\xf3 thể th\xeam 呢. Lưu \xfd 在 c\xf2n l\xe0 giới từ chỉ nơi chốn, ở đ\xe2y l\xe0 ph\xf3 từ.",examples:["我去过中国。[wǒ q\xf9 guo Zhōnggu\xf3] (T\xf4i đ\xe3 từng đến Trung Quốc.)","我没吃过北京烤鸭。[wǒ m\xe9i chī guo Běijīng kǎoyā] (T\xf4i chưa từng ăn vịt quay Bắc Kinh.)","他正在打电话。[tā zh\xe8ngz\xe0i dǎ di\xe0nhu\xe0] (Anh ấy đang gọi điện thoại.)"],questions:[{prompt:"Điền v\xe0o chỗ trống: 「你吃___饺子吗?」(Bạn đ\xe3 từng ăn sủi cảo chưa?)",options:["过","着","完"],answer:0,explanation:"V + 过 hỏi về kinh nghiệm."},{prompt:"“T\xf4i đang học tiếng Trung.” l\xe0:",options:["我正在学中文。","我学中文过。","我学了中文在。"],answer:0,explanation:"正在 + động từ: h\xe0nh động đang diễn ra."},{prompt:"Phủ định của 「我去过北京。」 l\xe0:",options:["我没去过北京。","我不去过北京。","我没有去北京过。"],answer:0,explanation:"没 + V + 过."}]},{id:"bi-comparison",level:"A2",title:"So s\xe1nh với 比",structure:"A 比 B + Adj / A 比 B + 更/还 + Adj / A 没有 B + Adj",overview:"C\xe2u so s\xe1nh hơn d\xf9ng 比: A 比 B + t\xednh từ. Kh\xf4ng d\xf9ng 很 trước t\xednh từ trong c\xe2u 比; muốn nhấn mạnh d\xf9ng 更 hoặc 还. Muốn n\xf3i ch\xeanh lệch bao nhi\xeau, th\xeam số lượng sau t\xednh từ (高五厘米). So s\xe1nh kh\xf4ng bằng d\xf9ng 没有: A 没有 B + t\xednh từ.",examples:["今天比昨天冷。[jīntiān bǐ zu\xf3tiān lěng] (H\xf4m nay lạnh hơn h\xf4m qua.)","他比我高五厘米。[tā bǐ wǒ gāo wǔ l\xedmǐ] (Anh ấy cao hơn t\xf4i 5 cm.)","我没有他高。[wǒ m\xe9iyǒu tā gāo] (T\xf4i kh\xf4ng cao bằng anh ấy.)"],questions:[{prompt:"Chọn c\xe2u đ\xfang: “C\xf4 ấy lớn hơn t\xf4i.”",options:["她比我大。","她比我很大。","她很比我大。"],answer:0,explanation:"Trong c\xe2u 比 kh\xf4ng d\xf9ng 很 trước t\xednh từ."},{prompt:"Điền v\xe0o chỗ trống: 「这个比那个___贵。」(đắt hơn nhiều)",options:["更","很","太"],answer:0,explanation:"D\xf9ng 更 hoặc 还 để nhấn mạnh trong c\xe2u 比."},{prompt:"“T\xf4i kh\xf4ng cao bằng anh ấy.” l\xe0:",options:["我没有他高。","我不比他高了。","我没比他高有。"],answer:0,explanation:"A 没有 B + Adj diễn tả kh\xf4ng bằng."}]},{id:"modal-verbs",level:"A2",title:"Động từ năng nguyện: 想, 要, 会, 能, 可以",structure:"S + 想/要/会/能/可以 + V",overview:"想: muốn, c\xf3 \xfd định. 要: muốn / cần / sắp. 会: biết l\xe0m nhờ học (会说中文) hoặc sẽ xảy ra. 能: c\xf3 khả năng hoặc điều kiện cho ph\xe9p l\xe0m. 可以: được ph\xe9p. Phủ định 不会 / 不能 / 不想, ri\xeang “kh\xf4ng được ph\xe9p” d\xf9ng 不可以 hoặc 不能. Đặt trước động từ ch\xednh, kh\xf4ng đặt sau.",examples:["我会说一点儿中文。[wǒ hu\xec shuō y\xecdiǎnr Zhōngw\xe9n] (T\xf4i biết n\xf3i một ch\xfat tiếng Trung.)","你能再说一遍吗?[nǐ n\xe9ng z\xe0i shuō y\xed bi\xe0n ma] (Bạn c\xf3 thể n\xf3i lại lần nữa kh\xf4ng?)","这里可以拍照吗?[zh\xe8lǐ kěyǐ pāizh\xe0o ma] (Ở đ\xe2y c\xf3 được chụp ảnh kh\xf4ng?)"],questions:[{prompt:"Điền v\xe0o chỗ trống: 「我___游泳。」(T\xf4i biết bơi.)",options:["会","可以","要"],answer:0,explanation:"会 diễn tả biết l\xe0m nhờ học."},{prompt:"Hỏi xin ph\xe9p “T\xf4i ngồi đ\xe2y được kh\xf4ng?” l\xe0:",options:["我可以坐这儿吗?","我会坐这儿吗?","我想坐这儿了吗?"],answer:0,explanation:"可以 d\xf9ng để xin hoặc cho ph\xe9p."},{prompt:"Điền v\xe0o chỗ trống: 「我感冒了,今天不___去上班。」(kh\xf4ng thể đi l\xe0m)",options:["能","会了","想了"],answer:0,explanation:"能 / 不能: c\xf3 / kh\xf4ng c\xf3 điều kiện l\xe0m việc g\xec."}]},{id:"ba-sentence",level:"B1",title:"C\xe2u chữ 把",structure:"S + 把 + O + V + th\xe0nh phần kh\xe1c (在 / 到 / 给 / 了 / bổ ngữ)",overview:"C\xe2u 把 nhấn mạnh việc xử l\xfd một t\xe2n ngữ đ\xe3 x\xe1c định v\xe0 kết quả của n\xf3. T\xe2n ngữ đưa l\xean trước động từ nhờ 把; động từ kh\xf4ng đứng trơ trọi m\xe0 phải k\xe8m th\xe0nh phần kh\xe1c như 了, bổ ngữ kết quả/xu hướng, hoặc 在/到/给 + nơi chốn. Kh\xf4ng d\xf9ng 把 với động từ kh\xf4ng t\xe1c động l\xean vật như 有, 是, 喜欢.",examples:["请把门关上。[qǐng bǎ m\xe9n guānshang] (L\xe0m ơn đ\xf3ng cửa lại.)","我把书放在桌子上了。[wǒ bǎ shū f\xe0ng z\xe0i zhuōzi shang le] (T\xf4i đ\xe3 đặt s\xe1ch l\xean b\xe0n.)","你把作业做完了吗?[nǐ bǎ zu\xf2y\xe8 zu\xf2 w\xe1n le ma] (Bạn l\xe0m xong b\xe0i tập chưa?)"],questions:[{prompt:"Chọn c\xe2u đ\xfang: “T\xf4i uống hết cốc nước rồi.”",options:["我把水喝完了。","我把水喝。","我喝把水完了。"],answer:0,explanation:"Sau động từ trong c\xe2u 把 cần th\xe0nh phần bổ sung: 喝完了."},{prompt:"C\xe2u n\xe0o SAI?",options:["我把他喜欢。","我把钥匙忘在家里了。","请把窗户打开。"],answer:0,explanation:"喜欢 kh\xf4ng d\xf9ng trong c\xe2u 把 v\xec kh\xf4ng xử l\xfd, t\xe1c động l\xean t\xe2n ngữ."},{prompt:"Điền v\xe0o chỗ trống: 「请你___这封信寄给他。」",options:["把","被","对"],answer:0,explanation:"把 + t\xe2n ngữ + động từ + 给 + người nhận."}]},{id:"complements",level:"B1",title:"Bổ ngữ trạng th\xe1i v\xe0 bổ ngữ kết quả",structure:"V + 得 + Adj / V + 完 / 好 / 到 / 见",overview:"Bổ ngữ trạng th\xe1i (V + 得 + t\xednh từ) đ\xe1nh gi\xe1 c\xe1ch thức h\xe0nh động: 说得很好. Nếu c\xf3 t\xe2n ngữ th\xec lặp động từ: 他说中文说得很好. Bổ ngữ kết quả đứng ngay sau động từ để chỉ kết quả: 看见, 听懂, 做完, 找到, 写好. Phủ định kết quả d\xf9ng 没: 没听懂.",examples:["她唱得很好听。[tā ch\xe0ng de hěn hǎotīng] (C\xf4 ấy h\xe1t rất hay.)","他说中文说得很流利。[tā shuō Zhōngw\xe9n shuō de hěn li\xfal\xec] (Anh ấy n\xf3i tiếng Trung rất lưu lo\xe1t.)","我没听懂,请再说一遍。[wǒ m\xe9i tīng dǒng, qǐng z\xe0i shuō y\xed bi\xe0n] (T\xf4i nghe chưa hiểu, xin n\xf3i lại lần nữa.)"],questions:[{prompt:"Điền v\xe0o chỗ trống: 「他跑___很快。」(Anh ấy chạy rất nhanh.)",options:["得","的","地"],answer:0,explanation:"V + 得 + t\xednh từ: bổ ngữ trạng th\xe1i."},{prompt:"“T\xf4i nghe kh\xf4ng hiểu.” l\xe0:",options:["我听不懂。","我听没懂。","我不听懂。"],answer:0,explanation:"听不懂 (bổ ngữ khả năng) hoặc 没听懂 (chưa nghe hiểu)."},{prompt:"Chọn c\xe2u đ\xfang: “Anh ấy viết chữ H\xe1n rất đẹp.”",options:["他写汉字写得很漂亮。","他写得汉字很漂亮。","他写汉字得很漂亮。"],answer:0,explanation:"C\xf3 t\xe2n ngữ th\xec lặp động từ: 写汉字写得……"}]},{id:"connectors",level:"B2",title:"Cặp li\xean từ v\xe0 连……都……",structure:"虽然……但是…… / 不但……而且…… / 既然……就…… / 连……都……",overview:"虽然……但是……: tuy… nhưng… (tiếng Trung d\xf9ng cả hai vế, kh\xe1c tiếng Việt thường bỏ một). 不但……而且……: kh\xf4ng chỉ… m\xe0 c\xf2n…. 既然……就……: đ\xe3… th\xec…. 连……都/也……: ngay cả… cũng…, nhấn mạnh một v\xed dụ cực đoan. D\xf9ng đ\xfang c\xe1c cặp n\xe0y gi\xfap văn n\xf3i v\xe0 văn viết ở HSK 5 tự nhi\xean hơn.",examples:["虽然很贵,但是质量很好。[suīr\xe1n hěn gu\xec, d\xe0nsh\xec zh\xecli\xe0ng hěn hǎo] (Tuy đắt nhưng chất lượng rất tốt.)","他不但会说中文,而且会写汉字。[tā b\xfad\xe0n hu\xec shuō Zhōngw\xe9n, \xe9rqiě hu\xec xiě H\xe0nz\xec] (Anh ấy kh\xf4ng chỉ n\xf3i được tiếng Trung m\xe0 c\xf2n viết được chữ H\xe1n.)","他忙得连饭都没吃。[tā m\xe1ng de li\xe1n f\xe0n dōu m\xe9i chī] (Anh ấy bận đến mức cơm cũng chưa ăn.)"],questions:[{prompt:"Điền v\xe0o chỗ trống: 「___你已经决定了,我___支持你。」",options:["既然……就","虽然……但是","不但……而且"],answer:0,explanation:"既然……就……: đ\xe3… th\xec…, dựa tr\xean một sự thật đ\xe3 r\xf5."},{prompt:"Điền v\xe0o chỗ trống: 「他___名字___不会写。」(Ngay cả t\xean anh ấy cũng kh\xf4ng biết viết.)",options:["连……都","因为……所以","如果……就"],answer:0,explanation:"连……都……: ngay cả… cũng…"},{prompt:"「虽然天气不好,___我们还是去了。」",options:["但是","所以","而且"],answer:0,explanation:"虽然 đi c\xf9ng 但是 / 可是 (nhưng)."}]}]}}}]);